use super::consts::DEFAULT_HEIGHT;
use super::consts::DEFAULT_WIDTH;

/// Public sizing policy for GPUI chart builders.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum ChartSize {
    /// Fill the parent while keeping stable minimum dimensions for plot layout.
    Fill {
        min_width: f32,
        min_height: f32,
        aspect_ratio: Option<f32>,
    },
    /// Use an explicit fixed pixel size.
    Fixed { width: f32, height: f32 },
}

impl Default for ChartSize {
    fn default() -> Self {
        Self::Fill {
            min_width: DEFAULT_WIDTH,
            min_height: DEFAULT_HEIGHT,
            aspect_ratio: None,
        }
    }
}

impl ChartSize {
    /// Create fill sizing with default minimum dimensions.
    pub fn fill() -> Self {
        Self::default()
    }

    /// Create fixed pixel sizing.
    pub fn fixed(width: f32, height: f32) -> Self {
        Self::Fixed { width, height }
    }

    /// Set minimum dimensions while preserving the current sizing policy.
    pub fn min_size(self, min_width: f32, min_height: f32) -> Self {
        match self {
            Self::Fill { aspect_ratio, .. } => Self::Fill {
                min_width,
                min_height,
                aspect_ratio,
            },
            Self::Fixed { .. } => Self::Fill {
                min_width,
                min_height,
                aspect_ratio: None,
            },
        }
    }

    /// Set the preferred chart aspect ratio for fill layouts.
    pub fn aspect_ratio(self, aspect_ratio: f32) -> Self {
        match self {
            Self::Fill {
                min_width,
                min_height,
                ..
            } => Self::Fill {
                min_width,
                min_height,
                aspect_ratio: Some(aspect_ratio),
            },
            Self::Fixed { width, height } => Self::Fill {
                min_width: width,
                min_height: height,
                aspect_ratio: Some(aspect_ratio),
            },
        }
    }

    /// Return the dimensions used for deterministic plot geometry.
    pub fn layout_dimensions(self) -> (f32, f32) {
        match self {
            Self::Fill {
                min_width,
                min_height,
                aspect_ratio,
            } => {
                let (mut width, mut height) = (min_width, min_height);
                if let Some(ratio) = aspect_ratio
                    && ratio.is_finite()
                    && ratio > 0.0
                    && width.is_finite()
                    && height.is_finite()
                    && width > 0.0
                    && height > 0.0
                {
                    let current = width / height;
                    if current < ratio {
                        width = height * ratio;
                    } else {
                        height = width / ratio;
                    }
                }
                (width, height)
            }
            Self::Fixed { width, height } => (width, height),
        }
    }
}

pub(crate) fn apply_chart_size(mut el: gpui::Div, size: ChartSize) -> gpui::Div {
    use gpui::Styled as _;

    match size {
        ChartSize::Fill { .. } => {
            let (layout_width, layout_height) = size.layout_dimensions();
            el = el
                .w_full()
                .h_full()
                .min_w(gpui::px(layout_width))
                .min_h(gpui::px(layout_height));
        }
        ChartSize::Fixed { .. } => {
            let (layout_width, layout_height) = size.layout_dimensions();
            el = el.w(gpui::px(layout_width)).h(gpui::px(layout_height));
        }
    }

    el
}

pub(crate) fn resolved_chart_dimensions(size: ChartSize) -> (f32, f32) {
    size.layout_dimensions()
}

